def recover_relations(response: str, atoms: dict[str, str]):
    relations = []
    sentences = response.split('. ')

    for sentence in sentences:
        for i in range(1, len(atoms) + 1):
            for j in range(1, len(atoms) + 1):
                if i != j:
                    if f'atom {i}' in sentence and f'atom {j}' in sentence:
                        # Cause-Effect
                        if 'caused' in sentence or 'led to' in sentence or 'resulted in' in sentence or 'because' in sentence:
                            relations.append({"source": i, "target": j, "sense": "Cause-Effect", "coupling": "entailment", "strength_band": "strong"})
