                        elif 'shows' in sentence or 'indicates' in sentence or 'confirms' in sentence or 'as shown by' in sentence:
                            relations.append({"source": i, "target": j, "sense": "Evidence", "coupling": "entailment", "strength_band": "strong"})
                        # Restatement
                        elif 'that is' in sentence or 'in other words' in sentence:
                            relations.append({"source": i, "target": j, "sense": "Restatement", "coupling": "equivalence", "strength_band": "strong"})
                        # Refutation
                        elif 'cannot be squared with' in sentence or 'rules out' in sentence or 'it cannot have, since' in sentence:
                            relations.append({"source": i, "target": j, "sense": "Refutation", "coupling": "contradiction", "strength_band": "strong"})
